import { useEffect, useState } from 'react';
import client from '../api/client';
import { useAuth } from '../context/AuthContext';

export default function ProjectsPage() {
  const { canEdit } = useAuth();
  const [projects, setProjects] = useState([]);
  const [selected, setSelected] = useState(new Set());
  const [tasks, setTasks] = useState([]);
  const [showNewProject, setShowNewProject] = useState(false);
  const [templates, setTemplates] = useState([]);
  const [newName, setNewName] = useState('');
  const [newTemplate, setNewTemplate] = useState('');
  const [creating, setCreating] = useState('');

  useEffect(() => {
    client.get('/projects').then((res) => setProjects(res.data));
    if (canEdit) client.get('/templates').then((res) => setTemplates(res.data));
  }, [canEdit]);

  useEffect(() => {
    if (selected.size === 0) { setTasks([]); return; }
    client.get('/tasks', { params: { project_gids: Array.from(selected).join(',') } })
      .then((res) => setTasks(res.data));
  }, [selected]);

  function toggle(gid) {
    const next = new Set(selected);
    next.has(gid) ? next.delete(gid) : next.add(gid);
    setSelected(next);
  }

  async function saveDate(taskGid, body) {
    try {
      await client.patch(`/tasks/${taskGid}`, body);
      client.get('/tasks', { params: { project_gids: Array.from(selected).join(',') } })
        .then((res) => setTasks(res.data));
    } catch (err) {
      alert('Failed to save to Asana: ' + (err.response?.data?.error || err.message));
    }
  }

  async function createProject() {
    if (!newName.trim()) return;
    setCreating('Working...');
    try {
      const res = newTemplate
        ? await client.post('/projects/duplicate', { templateGid: newTemplate, name: newName })
        : await client.post('/projects', { name: newName });
      setCreating('Created project ' + res.data.projectGid);
      setNewName('');
      client.get('/projects').then((r) => setProjects(r.data));
    } catch (err) {
      setCreating('Failed: ' + (err.response?.data?.error || err.message));
    }
  }

  return (
    <div style={{ display: 'flex', height: 'calc(100vh - 60px)' }}>
      <div style={{ width: 340, borderRight: '1px solid #e0e0e0', overflowY: 'auto', padding: 12 }}>
        {canEdit && (
          <div style={{ marginBottom: 12 }}>
            <button onClick={() => setShowNewProject(!showNewProject)} style={{ width: '100%' }}>+ New project</button>
            {showNewProject && (
              <div style={{ border: '1px solid #ddd', borderRadius: 6, padding: 10, marginTop: 8, fontSize: 12 }}>
                <input placeholder="Project name" value={newName} onChange={(e) => setNewName(e.target.value)}
                       style={{ width: '100%', marginBottom: 6, boxSizing: 'border-box' }} />
                <select value={newTemplate} onChange={(e) => setNewTemplate(e.target.value)} style={{ width: '100%', marginBottom: 6 }}>
                  <option value="">-- blank project --</option>
                  {templates.map((t) => <option key={t.gid} value={t.gid}>{t.name}</option>)}
                </select>
                <button onClick={createProject} style={{ width: '100%' }}>Create</button>
                {creating && <div style={{ marginTop: 6 }}>{creating}</div>}
              </div>
            )}
          </div>
        )}
        {projects.map((p) => (
          <div key={p.project_gid} onClick={() => toggle(p.project_gid)}
               style={{ display: 'flex', gap: 8, padding: '6px 4px', fontSize: 13, cursor: 'pointer', borderRadius: 4 }}>
            <input type="checkbox" checked={selected.has(p.project_gid)} readOnly />
            <span style={{ flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{p.project}</span>
            <span style={{ fontSize: 11, color: '#888' }}>{p.pct_complete ?? 0}%</span>
          </div>
        ))}
      </div>
      <div style={{ flex: 1, overflowY: 'auto', padding: 16 }}>
        {selected.size === 0 ? (
          <p style={{ color: '#888' }}>Select one or more projects to view tasks.</p>
        ) : (
          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13 }}>
            <thead>
              <tr style={{ background: '#fafafa' }}>
                <th style={th}>Task</th><th style={th}>Project</th><th style={th}>Assignee</th>
                <th style={th}>Due date</th><th style={th}>Expected Due Date</th>
              </tr>
            </thead>
            <tbody>
              {tasks.map((t) => (
                <TaskRow key={t.task_gid} task={t} canEdit={canEdit} onSave={saveDate} />
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

function TaskRow({ task, canEdit, onSave }) {
  const [dueOn, setDueOn] = useState(task.due_on ? task.due_on.slice(0, 10) : '');
  const [expDate, setExpDate] = useState((task.expected_due_date || '').slice(0, 10));

  return (
    <tr style={{ opacity: task.completed ? 0.5 : 1 }}>
      <td style={td}>{task.task_name}</td>
      <td style={td}>{task.project}</td>
      <td style={td}>{task.assignee || ''}</td>
      <td style={td}>
        <input type="date" value={dueOn} disabled={!canEdit}
               onChange={(e) => setDueOn(e.target.value)}
               onBlur={() => canEdit && onSave(task.task_gid, { dueOn: dueOn || null })} />
      </td>
      <td style={td}>
        {task.expected_due_date_field_gid ? (
          <input type="date" value={expDate} disabled={!canEdit}
                 onChange={(e) => setExpDate(e.target.value)}
                 onBlur={() => canEdit && onSave(task.task_gid, {
                   expectedDueDateFieldGid: task.expected_due_date_field_gid,
                   expectedDueDate: expDate || null,
                 })} />
        ) : <span style={{ color: '#bbb' }}>n/a</span>}
      </td>
    </tr>
  );
}

const th = { textAlign: 'left', padding: '8px 10px', borderBottom: '1px solid #eee' };
const td = { padding: '8px 10px', borderBottom: '1px solid #eee' };
